-- Ruins of Gilneas: "Resistance is Futile" (27423) asks for 20 kills of the Gilneas Liberation Front worgen, but none of
-- the six combatant entries (Bloodfang Scout 45481 and 45536, Worgen Battlemage 45483 and 45537, Gilnean Warhound
-- 45499 and 45538) was spawned, so the quest could not be progressed. Their templates also carried the level 1
-- friendly values of a kill credit proxy, so the worgen could not be attacked.
-- Based on Legends of Azeroth 5.4.8: the template values and the spawns (210 sniffed copies; the 179 kept are the ones
-- at least 3 yards from an earlier kept copy: 65 and 55 Scouts, 6 and 10 Battlemages, 24 and 19 Warhounds).
-- Copies that walk a patrol path stand still (as for the Worgen Rebels), the others wander 3 yards.
UPDATE `creature_template` SET `minlevel`=15, `maxlevel`=16, `faction_A`=2166, `faction_H`=2166, `unit_class`=4 WHERE `entry` IN (45481, 45536);
UPDATE `creature_template` SET `minlevel`=15, `maxlevel`=16, `faction_A`=2166, `faction_H`=2166, `unit_class`=2 WHERE `entry` IN (45483, 45537);
UPDATE `creature_template` SET `minlevel`=14, `maxlevel`=15, `faction_A`=2166, `faction_H`=2166 WHERE `entry` IN (45499, 45538);

DELETE FROM `creature` WHERE `guid` BETWEEN 9311610 AND 9311788;
